-- Project-level Haskell tasks, mirroring dune.lua. Works with both stack and
-- cabal: stack.yaml wins when present, since a stack project usually also
-- has a .cabal file (generated by hpack) that cabal would happily pick up
-- but with the wrong resolver/GHC.

local function find_root(dir)
	local stack = vim.fs.find("stack.yaml", { upward = true, type = "file", path = dir })[1]
	if stack then
		return "stack", vim.fs.dirname(stack)
	end

	local cabal = vim.fs.find(function(name)
		return name == "cabal.project" or name:match("%.cabal$") ~= nil
	end, { upward = true, type = "file", path = dir })[1]
	if cabal then
		return "cabal", vim.fs.dirname(cabal)
	end
end

-- `cabal run` / `stack run` with no target only works when there is exactly
-- one executable, so emit one run task per executable stanza instead.
local function find_executables(root)
	local exes = {}
	local files = vim.fs.find(function(name)
		return name:match("%.cabal$") ~= nil
	end, { type = "file", path = root, limit = math.huge })

	for _, file in ipairs(files) do
		if not file:find("/dist%-newstyle/") and not file:find("/%.stack%-work/") then
			for line in io.lines(file) do
				local exe = line:match("^[Ee]xecutable%s+(%S+)")
				if exe then
					table.insert(exes, exe)
				end
			end
		end
	end
	return exes
end

local function task(name, cmd, args, cwd)
	return {
		name = name,
		builder = function()
			return {
				cmd = { cmd },
				args = args,
				cwd = cwd,
				components = {
					"default",
				},
			}
		end,
	}
end

return {
	cache_key = function(opts)
		local _, root = find_root(opts.dir)
		return root
	end,
	generator = function(opts)
		local tool, root = find_root(opts.dir)
		if not tool then
			return "No stack.yaml or .cabal/cabal.project file found"
		end

		local tasks = {}
		if tool == "stack" then
			vim.list_extend(tasks, {
				task("stack build", "stack", { "build" }, root),
				task("stack watch", "stack", { "build", "--file-watch" }, root),
				task("stack test", "stack", { "test" }, root),
				task("stack ghci", "stack", { "ghci" }, root),
			})
		else
			vim.list_extend(tasks, {
				task("cabal build", "cabal", { "build", "all" }, root),
				task("cabal test", "cabal", { "test", "all", "--test-show-details=direct" }, root),
				task("cabal repl", "cabal", { "repl" }, root),
			})
		end

		for _, exe in ipairs(find_executables(root)) do
			table.insert(tasks, task(tool .. " run " .. exe, tool, { "run", exe }, root))
		end

		return tasks
	end,
}
